"use client";

import * as React from "react";
import { memo, useMemo, useState, useCallback } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { formatValue, useContainerDimensions, ChartTooltip } from "@/components/charts/_shared";
import type { TreemapChartTooltipData, TooltipRenderer } from "@/components/charts/_shared";
import { cn } from "@/lib/utils";
import { computeTreeMapLayout, nodeValue } from "./layout";
import type { TreeMapNode, LayoutRect } from "./layout";

// Re-export types
export type { TreeMapNode, LayoutRect };

// Props
export interface TreeMapChartProps {
  readonly data: readonly TreeMapNode[];
  readonly colors?: readonly string[];
  readonly className?: string;
  readonly height?: number;
  readonly loading?: boolean;
  readonly error?: string | null;
  readonly animation?: boolean;
  readonly onClick?: (node: TreeMapNode, path: readonly string[]) => void;
  readonly tooltipRenderer?: TooltipRenderer<TreemapChartTooltipData>;
}

// Constants
const DEFAULT_COLORS = [
  '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4',
] as const;

const DEFAULT_HEIGHT = 400;
const ANIMATION_EASING = [0.4, 0, 0.2, 1] as const;
const HOVER_DURATION = 0.2;
const MIN_LABEL_WIDTH = 40;
const MIN_LABEL_HEIGHT = 28;
const MIN_VALUE_HEIGHT = 44;


function colorWithOpacity(hex: string, opacity: number): string {
  const alpha = Math.round(opacity * 255).toString(16).padStart(2, '0');
  return hex + alpha;
}


// Loading State
function LoadingState({ height = DEFAULT_HEIGHT }: { height?: number }) {
  return (
    <div className="relative w-full" style={{ height }}>
      <div className="flex items-center justify-center h-full p-6">
        <div className="w-full h-full grid grid-cols-3 grid-rows-3 gap-1.5">
          {Array.from({ length: 9 }).map((_, i) => {
            const sizes = [
              'col-span-2 row-span-2',
              'col-span-1 row-span-1',
              'col-span-1 row-span-1',
              'col-span-1 row-span-1',
              'col-span-1 row-span-1',
              'col-span-1 row-span-1',
              'col-span-1 row-span-1',
              'col-span-1 row-span-1',
              'col-span-1 row-span-1',
            ];
            return (
              <div
                key={i}
                className={cn(
                  "bg-muted rounded animate-pulse",
                  sizes[i]
                )}
                style={{ animationDelay: `${i * 0.08}s` }}
              />
            );
          })}
        </div>
      </div>
    </div>
  );
}

function ErrorState({ error }: { error: string }) {
  return (
    <div className="flex items-center justify-center h-64">
      <div className="text-center space-y-2">
        <div className="text-destructive font-medium">Chart Error</div>
        <div className="text-sm text-muted-foreground">{error}</div>
      </div>
    </div>
  );
}

function EmptyState() {
  return (
    <div className="flex items-center justify-center h-64">
      <div className="text-center space-y-2">
        <div className="text-muted-foreground">No Data</div>
        <div className="text-sm text-muted-foreground">
          There&apos;s no data to display
        </div>
      </div>
    </div>
  );
}

// Main Component
function TreeMapChartComponent({
  data,
  colors = DEFAULT_COLORS,
  className,
  height = DEFAULT_HEIGHT,
  loading = false,
  error = null,
  animation = true,
  onClick,
  tooltipRenderer,
}: TreeMapChartProps) {
  const [containerRef, containerWidth] = useContainerDimensions();
  const [hoveredRect, setHoveredRect] = useState<LayoutRect | null>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  const reduceMotion = useReducedMotion();
  const shouldAnimate = animation && !reduceMotion;

  const rects = useMemo(() => {
    if (!containerWidth || !data.length) return [];
    return computeTreeMapLayout(data, containerWidth, height);
  }, [data, containerWidth, height]);

  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    const container = (e.currentTarget as HTMLElement).getBoundingClientRect();
    setMousePos({
      x: e.clientX - container.left,
      y: e.clientY - container.top,
    });
  }, []);

  const handleRectMouseEnter = useCallback((rect: LayoutRect) => {
    setHoveredRect(rect);
  }, []);

  const handleRectMouseLeave = useCallback(() => {
    setHoveredRect(null);
  }, []);

  const handleRectClick = useCallback((rect: LayoutRect) => {
    onClick?.(rect.node, rect.path);
  }, [onClick]);

  const handleKeyDown = useCallback((e: React.KeyboardEvent, rect: LayoutRect) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onClick?.(rect.node, rect.path);
    }
  }, [onClick]);

  if (loading) return <LoadingState height={height} />;
  if (error) return <ErrorState error={error} />;
  if (!data.length || data.every(d => nodeValue(d) <= 0)) return <EmptyState />;

  if (!containerWidth) {
    return (
      <div ref={containerRef} className={cn('relative w-full', className)} style={{ height }}>
        <div className="flex items-center justify-center h-full text-sm text-muted-foreground">
          Loading...
        </div>
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      className={cn('relative w-full', className)}
      style={{ height }}
      onMouseMove={handleMouseMove}
    >
      <svg
        width="100%"
        height={height}
        className="overflow-visible"
        role="img"
        aria-label={`Treemap chart with ${rects.length} segments`}
      >
        {rects.map((rect, i) => {
          const color = colors[rect.colorIndex % colors.length] || DEFAULT_COLORS[0];
          const fillOpacity = rect.depth === 0 ? 0.85 : Math.max(0.4, 0.85 - rect.depth * 0.15);
          const fillColor = colorWithOpacity(color, fillOpacity);
          const isHovered = hoveredRect === rect;
          const showName = rect.width >= MIN_LABEL_WIDTH && rect.height >= MIN_LABEL_HEIGHT;
          const showValue = rect.width >= MIN_LABEL_WIDTH && rect.height >= MIN_VALUE_HEIGHT;

          const motionProps = shouldAnimate ? {
            initial: { scaleX: 0, scaleY: 0, opacity: 0 },
            animate: { scaleX: 1, scaleY: 1, opacity: 1 },
            transition: {
              duration: 0.5,
              delay: i * 0.02,
              ease: ANIMATION_EASING,
            },
          } : {};

          const transformOrigin = `${rect.x}px ${rect.y}px`;

          return (
            <motion.g
              key={`${rect.path.join('/')}-${i}`}
              style={{ transformOrigin }}
              {...motionProps}
            >
              <rect
                x={rect.x}
                y={rect.y}
                width={rect.width}
                height={rect.height}
                fill={fillColor}
                rx={Math.min(3, rect.width / 4, rect.height / 4)}
                className="cursor-pointer touch-manipulation focus:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                style={{
                  filter: isHovered && !reduceMotion ? `brightness(1.2) drop-shadow(0 0 4px ${color})` : 'none',
                  transition: reduceMotion ? 'none' : `filter ${HOVER_DURATION}s ease-out`,
                }}
                tabIndex={0}
                role="graphics-symbol"
                aria-label={`${rect.node.name}: ${formatValue(nodeValue(rect.node))} (${rect.percentage.toFixed(1)}%)`}
                onMouseEnter={() => handleRectMouseEnter(rect)}
                onMouseLeave={handleRectMouseLeave}
                onFocus={() => handleRectMouseEnter(rect)}
                onBlur={handleRectMouseLeave}
                onClick={() => handleRectClick(rect)}
                onKeyDown={(e) => handleKeyDown(e, rect)}
              />

              {/* Labels inside rectangles */}
              {showName && (
                <text
                  x={rect.x + rect.width / 2}
                  y={rect.y + (showValue ? rect.height / 2 - 6 : rect.height / 2)}
                  textAnchor="middle"
                  dominantBaseline="middle"
                  fontSize={Math.min(12, rect.width / 6)}
                  className="fill-foreground pointer-events-none select-none"
                  style={{ fontWeight: 500 }}
                >
                  {rect.node.name.length > rect.width / 7
                    ? rect.node.name.slice(0, Math.floor(rect.width / 7)) + '\u2026'
                    : rect.node.name}
                </text>
              )}
              {showValue && (
                <text
                  x={rect.x + rect.width / 2}
                  y={rect.y + rect.height / 2 + 10}
                  textAnchor="middle"
                  dominantBaseline="middle"
                  fontSize={Math.min(10, rect.width / 8)}
                  className="fill-muted-foreground pointer-events-none select-none"
                >
                  {formatValue(nodeValue(rect.node))}
                </text>
              )}
            </motion.g>
          );
        })}
      </svg>

      {/* Tooltip */}
      {(() => {
        const tipColor = hoveredRect
          ? colors[hoveredRect.colorIndex % colors.length] || DEFAULT_COLORS[0]
          : DEFAULT_COLORS[0];
        const tipData: TreemapChartTooltipData | null = hoveredRect
          ? {
              name: hoveredRect.node.name,
              value: nodeValue(hoveredRect.node),
              formattedValue: formatValue(nodeValue(hoveredRect.node)),
              percentage: hoveredRect.percentage,
              path: hoveredRect.path,
              color: tipColor,
            }
          : null;

        return (
          <ChartTooltip
            visible={hoveredRect != null}
            x={Math.min(mousePos.x + 12, containerWidth - 160)}
            y={Math.max(10, mousePos.y - 60)}
          >
            {tipData && (
              tooltipRenderer ? tooltipRenderer(tipData) : (
                <>
                  <div className="flex items-center gap-2 mb-1">
                    <div
                      className="w-2.5 h-2.5 rounded-full"
                      style={{ backgroundColor: tipData.color }}
                    />
                    <span className="text-xs font-medium text-foreground whitespace-nowrap">
                      {tipData.name}
                    </span>
                  </div>
                  <div className="text-sm font-bold text-primary tabular-nums">
                    {tipData.formattedValue}
                  </div>
                  <div className="text-xs text-muted-foreground tabular-nums">
                    {tipData.percentage.toFixed(1)}% of total
                  </div>
                  {tipData.path.length > 1 && (
                    <div className="text-xs text-muted-foreground mt-1 pt-1 border-t border-border/50">
                      {tipData.path.join(' \u203A ')}
                    </div>
                  )}
                </>
              )
            )}
          </ChartTooltip>
        );
      })()}
    </div>
  );
}

export const TreeMapChart = memo(TreeMapChartComponent);
export { DEFAULT_COLORS };

/**
 * Squarified treemap layout algorithm.
 * Based on Bruls, Huizing, van Wijk (2000).
 * Pure functions — no side effects, fully testable.
 */

export interface TreeMapNode {
  readonly name: string;
  readonly value?: number;
  readonly children?: readonly TreeMapNode[];
}

export interface LayoutRect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly node: TreeMapNode;
  readonly depth: number;
  readonly colorIndex: number;
  readonly path: readonly string[];
  readonly percentage: number;
}

interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * Compute the total value of a node (leaf value or sum of children).
 */
export function nodeValue(node: TreeMapNode): number {
  if (node.children && node.children.length > 0) {
    return node.children.reduce((sum, child) => sum + nodeValue(child), 0);
  }
  return typeof node.value === 'number' && isFinite(node.value) && node.value > 0
    ? node.value
    : 0;
}

/**
 * Compute the aspect ratio of a rectangle.
 * Closer to 1 = more square-like = better.
 */
function aspectRatio(width: number, height: number): number {
  if (width === 0 || height === 0) return Infinity;
  return Math.max(width / height, height / width);
}

/**
 * Worst aspect ratio in a row of items laid out along the short side.
 */
function worstRatio(row: number[], sideLength: number, totalArea: number): number {
  if (row.length === 0 || sideLength <= 0) return Infinity;

  const rowSum = row.reduce((a, b) => a + b, 0);
  if (rowSum <= 0) return Infinity;

  const rowWidth = (rowSum / totalArea) * sideLength;
  let worst = 0;

  for (const area of row) {
    const itemHeight = area / rowWidth;
    const ratio = aspectRatio(rowWidth, itemHeight);
    if (ratio > worst) worst = ratio;
  }

  return worst;
}

/**
 * Layout a single row of items within the remaining rect.
 * Returns the rectangles for each item and the remaining rect.
 */
function layoutRow(
  row: { area: number; index: number }[],
  rect: Rect,
  totalArea: number
): { rects: { x: number; y: number; width: number; height: number; index: number }[]; remaining: Rect } {
  const rowSum = row.reduce((sum, item) => sum + item.area, 0);
  const isHorizontal = rect.width >= rect.height;

  const rects: { x: number; y: number; width: number; height: number; index: number }[] = [];

  if (isHorizontal) {
    const rowWidth = totalArea > 0 ? (rowSum / totalArea) * rect.width : 0;
    let y = rect.y;

    for (const item of row) {
      const itemHeight = rowSum > 0 ? (item.area / rowSum) * rect.height : 0;
      rects.push({ x: rect.x, y, width: rowWidth, height: itemHeight, index: item.index });
      y += itemHeight;
    }

    return {
      rects,
      remaining: {
        x: rect.x + rowWidth,
        y: rect.y,
        width: rect.width - rowWidth,
        height: rect.height,
      },
    };
  } else {
    const rowHeight = totalArea > 0 ? (rowSum / totalArea) * rect.height : 0;
    let x = rect.x;

    for (const item of row) {
      const itemWidth = rowSum > 0 ? (item.area / rowSum) * rect.width : 0;
      rects.push({ x, y: rect.y, width: itemWidth, height: rowHeight, index: item.index });
      x += itemWidth;
    }

    return {
      rects,
      remaining: {
        x: rect.x,
        y: rect.y + rowHeight,
        width: rect.width,
        height: rect.height - rowHeight,
      },
    };
  }
}

/**
 * Squarified treemap: lay out items to minimize worst aspect ratio.
 */
function squarify(
  items: { area: number; index: number }[],
  rect: Rect,
  totalArea: number
): { x: number; y: number; width: number; height: number; index: number }[] {
  if (items.length === 0 || totalArea <= 0) return [];
  if (items.length === 1) {
    const first = items[0]!;
    return [{ x: rect.x, y: rect.y, width: rect.width, height: rect.height, index: first.index }];
  }

  const sideLength = Math.min(rect.width, rect.height);
  const result: { x: number; y: number; width: number; height: number; index: number }[] = [];

  let currentRow: { area: number; index: number }[] = [];
  let remaining = items.slice();

  while (remaining.length > 0) {
    const item = remaining[0]!;
    const testRow = [...currentRow, item];

    const currentWorst = worstRatio(
      currentRow.map(r => r.area),
      sideLength,
      totalArea
    );
    const testWorst = worstRatio(
      testRow.map(r => r.area),
      sideLength,
      totalArea
    );

    if (currentRow.length === 0 || testWorst <= currentWorst) {
      currentRow.push(item);
      remaining = remaining.slice(1);
    } else {
      const { rects, remaining: newRect } = layoutRow(currentRow, rect, totalArea);
      result.push(...rects);

      const remainingArea = remaining.reduce((sum, r) => sum + r.area, 0);
      const innerRects = squarify(remaining, newRect, remainingArea);
      result.push(...innerRects);
      return result;
    }
  }

  if (currentRow.length > 0) {
    const { rects } = layoutRow(currentRow, rect, totalArea);
    result.push(...rects);
  }

  return result;
}

const GAP = 1.5;

/**
 * Compute the full treemap layout from hierarchical data.
 */
export function computeTreeMapLayout(
  data: readonly TreeMapNode[],
  width: number,
  height: number,
): readonly LayoutRect[] {
  if (!data.length || width <= 0 || height <= 0) return [];

  const grandTotal = data.reduce((sum, node) => sum + nodeValue(node), 0);
  if (grandTotal <= 0) return [];

  const result: LayoutRect[] = [];

  function layoutChildren(
    nodes: readonly TreeMapNode[],
    rect: Rect,
    depth: number,
    parentColorIndex: number,
    parentPath: readonly string[],
  ): void {
    const values = nodes.map(node => nodeValue(node));
    const total = values.reduce((a, b) => a + b, 0);
    if (total <= 0) return;

    // Sort descending for better squarification
    const indexed: { node: TreeMapNode; value: number; originalIndex: number }[] = nodes.map((node, i) => ({
      node,
      value: values[i] ?? 0,
      originalIndex: i,
    }));
    indexed.sort((a, b) => b.value - a.value);

    const items: { area: number; index: number }[] = indexed.map((entry, i) => ({
      area: entry.value,
      index: i,
    }));

    const rects = squarify(items, rect, total);

    for (const r of rects) {
      const entry = indexed[r.index]!;
      const colorIdx = depth === 0 ? entry.originalIndex : parentColorIndex;
      const path = [...parentPath, entry.node.name];

      // Apply gap
      const gx = Math.min(GAP, r.width / 4);
      const gy = Math.min(GAP, r.height / 4);
      const gappedRect = {
        x: r.x + gx,
        y: r.y + gy,
        width: Math.max(0, r.width - gx * 2),
        height: Math.max(0, r.height - gy * 2),
      };

      if (entry.node.children && entry.node.children.length > 0 && gappedRect.width > 10 && gappedRect.height > 10) {
        layoutChildren(entry.node.children, gappedRect, depth + 1, colorIdx, path);
      } else {
        result.push({
          ...gappedRect,
          node: entry.node,
          depth,
          colorIndex: colorIdx,
          path,
          percentage: (entry.value / grandTotal) * 100,
        });
      }
    }
  }

  layoutChildren(data, { x: 0, y: 0, width, height }, 0, 0, []);
  return result;
}
